def lru_cache(maxsize=128, typed=False):
    def _lru_cache_decorator(func):
        cache = {}
        last_access = {}
        mru = 0
        def _lru_cache_wrapper(*args):
            key = args[1:]
            if typed:
                key += (type(args[0]),)
            if key in cache:
                res = cache[key]
                last_access[key] = mru
                return res
            res = func(*args)
            if len(cache) >= maxsize:
                # find the least recently used item
                lru = [k for k, a in last_access.items() if a == min(last_access.values())][0]
                del cache[lru]
                del last_access[lru]
            cache[key] = res
            last_access[key] = mru
            return res
        return _lru_cache_wrapper
    return _lru_cache_decorator

