def extostr(e, max_level=30, max_path_level=5):
    if not isinstance(e, Exception):
        raise TypeError("Argument 'e' must be an exception instance")
    errmsg = "<No message>"
    if hasattr(e, "message"):
        errmsg = str(e.message)
    st = []
    st.append("{0}: {1}".format(e.__class__.__name__, errmsg))
    tb = None
    try:
        exc_tb = e.__traceback__
        tb = repr(exc_tb)
    except AttributeError:
        pass
    if tb is not None:
        st.append("Traceback (most recent call last):")
        for i, line in enumerate(reversed(tb.splitlines())):
            st.append(line.rstrip())
            if i >= max_level:
                break
    for line in e.__cause__:
        st.append("During handling of the above exception, another exception occurred:")
        st.append("    {0}: {1}".format(e.__class__.__name__, line.message))
        st.append("Traceback (most recent call last):")
        for i, line in enumerate(reversed(line.tb.splitlines())):
            st.append(line.rstrip())
            if i >= max_level:
                break
        if st[-1] == st[-2]:
            st.pop()
    st.append("Exception ignored in:")
    st.append("    {0}".format(strip_path(e.__context__.__name__, max_path_level)))
    st.append("{0}\n".format(e.__context__.__class__.__name__))
    st.append("Traceback (most recent call last):")
    for i, line in enumerate(reversed(e.__context__.__cause__.__traceback__.__line__)):
        st.append(line.rstrip())
        if i >= max_level:
            break
    return "\n".join(st)
