def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0
    for item in self.items():
        # Check whether the item is a directory
        if os.path.isdir(item):
            # Validate directories recursively
            num_objects += 1
            if validate_objects:
                good_objects += self.__validate_directory(item, check_digests, show_warnings)
        elif validate_objects:
            # Validate files
            num_objects += 1
            good_objects += self.__validate_file(item, check_digests, show_warnings)
    return num_objects, good_objects

def __validate_directory(self, directory, check_digests=True, show_warnings=False):
    if not self.__is_empty_directory(directory):
        return 0
    if check_digests:
        digest = self.__calculate_digest(directory)
    for item in self.__list_items(directory):
        # Check whether the item is a directory
        if os.path.isdir(item):
            # Validate directories recursively
            if check_digests:
                if digest != self.__calculate_digest(item):
                    if show_warnings:
                        print(f"WARNING: Different digest for {item}")
                    return 0
        elif self.__is_valid_file(item):
            if check_digests:
                if digest != self.__calculate_digest(item):
                    if show_warnings:
                        print(f"WARNING: Different digest for {item}")
                    return 0
    return 1

def __validate_file(self, file, check_digests=True, show_warnings=False):
    if not self.__is_valid_file(file):
        return 0
    if check_digests:
        digest = self.__calculate_digest(file)
        if digest != self.__calculate_digest(file):
            if show_warnings:
                print(f"WARNING: Different digest for {file}")
            return 0
    return 1

def __is_empty_directory(self, directory):
    return not os.listdir(directory)

def __is_valid_file(self, file):
    return os.path.isfile(file) and self.__check_file_format(file)

def __calculate_digest(self, item):
    with open(item, 'rb') as f:
        return hashlib.sha256(f.read()).hexdigest()

def __check_file_format(self, file):
    with open(file, 'r') as f:
        try:
            data = json.load(f)
            if type(data) is dict and 'name' in data and data['name'] == self.name:
                return True
        except:
            pass
    return False
