def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files. """

        if not isinstance(parser_dict, dict):
            raise ValueError(f"parser_dict must be a dict but received {type(parser_dict)}")

        for key, value in parser_dict.items():
            if isinstance(value, dict):
                for sub_key, sub_value in value.items():
                    if sub_key == "include":
                        parser_dict[key] = self._resolve_include_directive(sub_value)
                    else:
                        parser_dict[key] = self._include_groups(value)
            elif isinstance(value, list):
                for idx, sub_value in enumerate(value):
                    if isinstance(sub_value, dict):
                        parser_dict[key][idx] = self._include_groups(sub_value)
                    else:
                        parser_dict[key][idx] = sub_value
            else:
                parser_dict[key] = value

        return parser_dict


