def get_nested_custom_and_control_args(args):
    control_args = {}
    nested_args = {}

    for arg in args:
        if arg.startswith("control:"):
            var, value = arg.lstrip("control:").split("=")
            control_args[var] = value
        elif arg.startswith("nested:"):
            var, value = arg.lstrip("nested:").split("=")
            nested_args[var] = value
        elif arg.startswith("custom:"):
            var, value = arg.lstrip("custom:").split("=")
            nested_args[var] = value

    return control_args, nested_args
