def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    # Validate input parameters
    if not isinstance(ir_workspace, Workspace):
        raise TypeError("ir_workspace parameter must be a Workspace object")
    if not isinstance(ir_plugin, InfraredPlugin):
        raise TypeError("ir_plugin parameter must be an InfraredPlugin object")
    if not isinstance(playbook_path, str):
        raise TypeError("playbook_path parameter must be a string")
    if verbose is not None and not isinstance(verbose, int):
        raise TypeError("verbose parameter must be an int")
    if extra_vars is not None and not isinstance(extra_vars, dict):
        raise TypeError("extra_vars parameter must be a dict")
    if ansible_args is not None and not isinstance(ansible_args, dict):
        raise TypeError("ansible_args parameter must be a dict")

    # Get the Infrared CLI command
    command = ir_plugin.get_ansible_command()

    # Build the command-line arguments
    args = [command, playbook_path]
    if verbose is not None:
        args.append("-v")
        args.append(str(verbose))
    if extra_vars:
        args.append("--extra-vars")
        args.append(json.dumps(extra_vars))
    if ansible_args:
        args.extend(ansible_args)

    # Run the Infrared CLI command
    try:
        subprocess.run(args, check=True)
    except subprocess.CalledProcessError as e:
        raise AnsibleRunError(e)
