def get_plugin_spec_flatten_dict(plugin_dir):
    if not plugin_dir:
        raise ValueError("Missing argument: plugin_dir")

    with open(os.path.join(plugin_dir, "spec.json")) as f:
        spec = json.load(f)

    flat_dict = {}

    for key, value in spec.items():
        if isinstance(value, dict):
            flat_dict.update({f"{key}.{k}": v for k, v in value.items()})
        else:
            flat_dict[key] = value

    return flat_dict

